@ w.T - b) @ c\n49:     error = torch.abs(actual.double() - expected)\n50:     structural = (actual.dtype == torch.float32 and actual.shape == (41,)\n51:                   and bool(torch.isfinite(actual).all())\n52:                   and all(torch.equal(a, z) for a, z in zip(inputs, before)))\n53:     return {\"scope\": \"41 smoke rows: origin, signed coordinate axes, and 16 uniform box samples\",\n54:             \"max_absolute_error\": float(error.max()), \"tolerance\": 1.0,\n55:             \"shape_dtype_finite_and_inputs_unmodified\": bool(structural),\n56:             \"all_passed\": bool(structural and float(error.max()) <= 1.0)}",
